func ValidateRemoval(account awsv1alpha1.Account) error {
	if !account.IsFailed() {
		return &AccountValidationError{
			Type: AccountNotForCleanup,
			Err:  errors.New("Account not in failed state"),
		}
	}

	if account.HasAwsAccountID() {
		return &AccountValidationError{
			Type: AccountNotForCleanup,
			Err:  errors.New("Account has an AwsAccountID - cannot delete"),
