func TestValidateAwsAccountId(t *testing.T) {
	type args struct {
		account awsv1alpha1.Account
	}
	tests := []struct {
		name    string
		args    args
		wantErr bool
	}{
		{
			name: "Throws an error if no AwsAccountId is found",
			args: args{
				account: awsv1alpha1.Account{
					TypeMeta: v1.TypeMeta{
						Kind:       "Account",
						APIVersion: "v1alpha1",
					},
					ObjectMeta: v1.ObjectMeta{
						Name:      "test",
						Namespace: "default",
					},
				},
			},
			wantErr: true,
		},
		{
			name: "Returns nil when an AwsAccountId is present",
			args: args{
				account: awsv1alpha1.Account{
					TypeMeta:   v1.TypeMeta{Kind: "Account", APIVersion: "v1alpha1"},
					ObjectMeta: v1.ObjectMeta{Name: "test", Namespace: "default"},
					Spec: awsv1alpha1.AccountSpec{
						AwsAccountID: "123456",
					},
				},
			},
			wantErr: false,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if err := ValidateAwsAccountId(tt.args.account); (err != nil) != tt.wantErr {
				t.Errorf("ValidateAwsAccountAssociated() error = %v, wantErr %v", err, tt.wantErr)
			}
		})
	}
}

func TestValidateRemoval(t *testing.T) {
	type args struct {
		account awsv1alpha1.Account
	}
	tests := []struct {
		name        string
		args        args
		wantErr     bool
		expectedErr string
	}{
		{
			name: "Account not in a failed state should not be removed",
			args: args{
				account: awsv1alpha1.Account{
					ObjectMeta: v1.ObjectMeta{
						Name:      "testaccount",
						Namespace: "testnamespace",
					},
					Status: awsv1alpha1.AccountStatus{
						State: string(awsv1alpha1.AccountReady),
					},
				},
			},
			wantErr:     true,
			expectedErr: "Account not in failed state",
		},
		{
			name: "Failed account with an AWS account ID should not be removed",
			args: args{
				account: awsv1alpha1.Account{
					ObjectMeta: v1.ObjectMeta{
						Name:      "testaccount",
						Namespace: "testnamespace",
					},
					Spec: awsv1alpha1.AccountSpec{
						AwsAccountID: "123456",
					},
					Status: awsv1alpha1.AccountStatus{
						State: string(awsv1alpha1.AccountFailed),
					},
				},
			},
			wantErr:     true,
			expectedErr: "Account has an AWS account ID",
		},
		{
			name: "Failed account with no AWS account ID should be removed",
			args: args{
				account: awsv1alpha1.Account{
					ObjectMeta: v1.ObjectMeta{
						Name:      "testaccount",
						Namespace: "testnamespace",
					},
					Status: awsv1alpha1.AccountStatus{
						State: string(awsv1alpha1.AccountFailed),
					},
				},
			},
			wantErr: false,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := ValidateRemoval(tt.args.account)
			if (err != nil) != tt.wantErr {
				t.Errorf("ValidateRemoval() error = %v, wantErr %v", err, tt.wantErr)
			}
			if tt.wantErr {
				validationError, ok := err.(*AccountValidationError)
				if !ok {
					t.Errorf("ValidateRemoval() error, expected AccountValidationError")
				}
				if validationError.Type != AccountNotForCleanup {
					t.Errorf("ValidateRemoval() error, expected error of type AccountNotForCleanup but was %v", validationError.Type)
				}
				if validationError.Err.Error() != tt.expectedErr {
					t.Errorf("ValidateRemoval() error, did not get correct error message")
				}
			}
		})
	}
}

