// enableOptInRegions submits the enablement request for the given region. The region
// is enabled via the EC2 DescribeRegions API's opt-in status for the account.
func enableOptInRegions(reqLogger logr.Logger, client awsclient.Client, regionCode string) (bool, error) {
	status, err := getRegionOptInStatus(client, regionCode)
	if err != nil {
		return false, err
	}

	if status == regionNotOptedIn {
		reqLogger.Info(fmt.Sprintf("Opt-In requested for RegionCode [%s]", regionCode))
		return true, nil
	}

	return false, nil
}

// RegionNeedsOptIn returns true if the given region still requires opt-in enablement
// for the account.
func RegionNeedsOptIn(reqLogger logr.Logger, client awsclient.Client, regionCode string) (bool, error) {
	status, err := getRegionOptInStatus(client, regionCode)
	if err != nil {
		return false, err
	}

	if status == regionNotOptedIn {
		reqLogger.Info(fmt.Sprintf("Region: %s requires enablement", regionCode))
		return true, nil
	}

	// Otherwise return false (doesn't need enablement)
	return false, nil
}

// checkOptInRegionStatus returns the current opt-in request status for the given region.
func checkOptInRegionStatus(reqLogger logr.Logger, awsClient awsclient.Client, regionCode string) (awsv1alpha1.OptInRequestStatus, error) {
	status, err := getRegionOptInStatus(awsClient, regionCode)
	if err != nil {
		return awsv1alpha1.OptInRequestTodo, err
	}

	switch status {
	case regionOptedIn, regionOptInNotRequired:
		return awsv1alpha1.OptInRequestEnabled, nil
	case regionNotOptedIn:
		return awsv1alpha1.OptInRequestTodo, nil
	}

	return awsv1alpha1.OptInRequestTodo, nil
}

// getRegionOptInStatus retrieves the opt-in status of the given region for the account
// using the EC2 DescribeRegions API.
func getRegionOptInStatus(awsClient awsclient.Client, regionCode string) (string, error) {
	var result *ec2.DescribeRegionsOutput

	// Default is 1/10 of a second, but any retries we need to make should be delayed a few seconds
	// This also defaults to an exponential backoff, so we only need to try ~5 times, default is 10
	retry.DefaultDelay = 3 * time.Second
	retry.DefaultAttempts = uint(5)
	err := retry.Do(
		func() (err error) {
			result, err = awsClient.DescribeRegions(&ec2.DescribeRegionsInput{
				AllRegions:  aws.Bool(true),
				RegionNames: aws.StringSlice([]string{regionCode}),
			})
			return err
		},
		// Retry if we receive some specific errors: access denied, rate limit or server-side error
		retry.RetryIf(func(err error) bool {
			if aerr, ok := err.(awserr.Error); ok {
				switch aerr.Code() {
				case "AccessDeniedException":
					return true
				case "InternalServerException":
					return true
				case "TooManyRequestsException":
					return true
				// Can be caused by the client token not yet propagated
				case "UnrecognizedClientException":
					return true
				}
			}
			// Otherwise, do not retry
			return false
		}),
	)

	if err != nil {
		return "", err
	}

	if result == nil {
		return "", fmt.Errorf("returned DescribeRegionsOutput is nil")
	}

	for _, region := range result.Regions {
		if region.OptInStatus != nil {
			return *region.OptInStatus, nil
		}
	}

	return "", nil
}

// ParseDisabledRegions parses a comma-separated list of disabled region codes into a set.
func ParseDisabledRegions(disabledRegions string) map[string]bool {
	disabled := make(map[string]bool)
	if disabledRegions == "" {
		return disabled
	}
	for _, region := range strings.Split(disabledRegions, ",") {
		region = strings.TrimSpace(region)
		if region != "" {
			disabled[region] = true
		}
	}
	return disabled
}

// SetOptRegionStatus updates the account status to indicate that all supported opt-in
// regions are pending enablement.
func SetOptRegionStatus(reqLogger logr.Logger, optInRegions []string, currentAcctInstance *awsv1alpha1.Account) error {
	reqLogger.Info("Setting Opt-In region status to todo of all Supported Opt-In regions")
	currentAcctInstance.Status.OptInRegions = make(awsv1alpha1.OptInRegions)
	for _, region := range optInRegions {
		currentAcctInstance.Status.OptInRegions[region] = &awsv1alpha1.OptInRegionStatus{
			RegionCode: region,
			Status:     awsv1alpha1.OptInRequestTodo,
		}
	}
	return nil
}

// CalculateOptingInRegionAccounts returns the number of accounts that currently have
// region opt-in enablement in progress or pending.
func CalculateOptingInRegionAccounts(reqLogger logr.Logger, c client.Client) (int, error) {
	// Retrieve a list of accounts with region enablement in progress for supported Opt-In regions
	accountList := &awsv1alpha1.AccountList{}
	listOpts := []client.ListOption{
		client.InNamespace(awsv1alpha1.AccountCrNamespace),
	}
	numberOfAccountsOptingIn := 0

	if err := c.List(context.TODO(), accountList, listOpts...); err != nil {
		log.Error(err, "Failed to list accounts")
		if k8serr.IsNotFound(err) {
			// Request object not found, could have been deleted after reconcile request.
			// Owned objects are automatically garbage collected. For additional cleanup logic use finalizers.
			// Return and don't requeue
			return numberOfAccountsOptingIn, err
		}
		// Error reading the object - requeue the request.
		return numberOfAccountsOptingIn, err
	}

	// since it's not possible to filter on custom field values when listing using the golang client
	// manual filtering of accounts opting-in is required to ensure the account limit is not reached
	for _, acct := range accountList.Items {
		if acct.Status.State == string(awsv1alpha1.AccountOptingInRegions) || (acct.IsReady() && acct.HasOpenOptInRegionRequests()) {
			numberOfAccountsOptingIn += 1
		}
	}
	reqLogger.Info(
		fmt.Sprintf("Current number of accounts opting into regions: [%d]",
			numberOfAccountsOptingIn),
	)

	return numberOfAccountsOptingIn, nil
}

