func Test_Account_GetOptInRequestsByStatus(t *testing.T) {
	tests := []struct {
		name       string
		acct       Account
		status     OptInRequestStatus
		wantCount  int
		wantRegion string
	}{
		{
			name: "No opt-in regions",
			acct: Account{
				Status: AccountStatus{OptInRegions: OptInRegions{}},
			},
			status:     OptInRequestTodo,
			wantCount:  0,
			wantRegion: "",
		},
		{
			name: "Counts regions with matching status",
			acct: Account{
				Status: AccountStatus{
					OptInRegions: OptInRegions{
						"af-south-1": &OptInRegionStatus{RegionCode: "af-south-1", Status: OptInRequestTodo},
						"ap-east-1":  &OptInRegionStatus{RegionCode: "ap-east-1", Status: OptInRequestEnabled},
					},
				},
			},
			status:     OptInRequestTodo,
			wantCount:  1,
			wantRegion: "af-south-1",
		},
		{
			name: "Counts enabling regions",
			acct: Account{
				Status: AccountStatus{
					OptInRegions: OptInRegions{
						"af-south-1": &OptInRegionStatus{RegionCode: "af-south-1", Status: OptInRequestEnabling},
					},
				},
			},
			status:     OptInRequestEnabling,
			wantCount:  1,
			wantRegion: "af-south-1",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			count, regions := tt.acct.GetOptInRequestsByStatus(tt.status)
			if count != tt.wantCount {
				t.Errorf("GetOptInRequestsByStatus() count = %d, want %d", count, tt.wantCount)
			}
			if tt.wantRegion != "" {
				region, ok := regions[tt.wantRegion]
				if !ok {
					t.Errorf("GetOptInRequestsByStatus() region %s not found in result", tt.wantRegion)
				}
				if region.Status != tt.status {
					t.Errorf("GetOptInRequestsByStatus() region status = %v, want %v", region.Status, tt.status)
				}
			}
		})
	}
}

