package account

import (
	"testing"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/service/ec2"
	"github.com/go-logr/logr"
	apis "github.com/openshift/aws-account-operator/api"
	awsv1alpha1 "github.com/openshift/aws-account-operator/api/v1alpha1"
	"github.com/openshift/aws-account-operator/pkg/awsclient/mock"
	"github.com/openshift/aws-account-operator/pkg/testutils"
	"go.uber.org/mock/gomock"
	corev1 "k8s.io/api/core/v1"
	"k8s.io/apimachinery/pkg/runtime"
	"k8s.io/client-go/kubernetes/scheme"
	"sigs.k8s.io/controller-runtime/pkg/client/fake"
)

func TestAccount_CalculateOptingInRegionAccounts(t *testing.T) {
	err := apis.AddToScheme(scheme.Scheme)
	if err != nil {
		t.Fatalf("failed adding to scheme in region_enablement_test.go: %v", err)
	}

	nullLogger := testutils.NewTestLogger().Logger()

	readyOpenRequests := &awsv1alpha1.Account{
		TypeMeta:   metav1.TypeMeta{Kind: "Account", APIVersion: "v1alpha1"},
		ObjectMeta: metav1.ObjectMeta{Name: "ready-open", Namespace: awsv1alpha1.AccountCrNamespace},
		Status: awsv1alpha1.AccountStatus{
			State: string(awsv1alpha1.AccountReady),
			OptInRegions: awsv1alpha1.OptInRegions{
				"af-south-1": &awsv1alpha1.OptInRegionStatus{RegionCode: "af-south-1", Status: awsv1alpha1.OptInRequestTodo},
			},
		},
	}

	readyNoOpenRequests := &awsv1alpha1.Account{
		TypeMeta:   metav1.TypeMeta{Kind: "Account", APIVersion: "v1alpha1"},
		ObjectMeta: metav1.ObjectMeta{Name: "ready-complete", Namespace: awsv1alpha1.AccountCrNamespace},
		Status: awsv1alpha1.AccountStatus{
			State: string(awsv1alpha1.AccountReady),
			OptInRegions: awsv1alpha1.OptInRegions{
				"af-south-1": &awsv1alpha1.OptInRegionStatus{RegionCode: "af-south-1", Status: awsv1alpha1.OptInRequestEnabled},
			},
		},
	}

	readyNoOptInRegions := &awsv1alpha1.Account{
		TypeMeta:   metav1.TypeMeta{Kind: "Account", APIVersion: "v1alpha1"},
		ObjectMeta: metav1.ObjectMeta{Name: "ready-no-regions", Namespace: awsv1alpha1.AccountCrNamespace},
		Status: awsv1alpha1.AccountStatus{
			State: string(awsv1alpha1.AccountReady),
		},
	}

	optingInRegions := &awsv1alpha1.Account{
		TypeMeta:   metav1.TypeMeta{Kind: "Account", APIVersion: "v1alpha1"},
		ObjectMeta: metav1.ObjectMeta{Name: "opting-in", Namespace: awsv1alpha1.AccountCrNamespace},
		Status: awsv1alpha1.AccountStatus{
			State: string(awsv1alpha1.AccountOptingInRegions),
		},
	}

	tests := []struct {
		name    string
		objects []runtime.Object
		want    int
	}{
		{
			name:    "No accounts opting in",
			objects: []runtime.Object{readyNoOpenRequests, readyNoOptInRegions},
			want:    0,
		},
		{
			name:    "Ready account with open opt-in requests is counted",
			objects: []runtime.Object{readyOpenRequests},
			want:    1,
		},
		{
			name:    "Account in OptingInRegions state is counted",
			objects: []runtime.Object{optingInRegions},
			want:    1,
		},
		{
			name:    "Accounts outside the account namespace are not counted",
			objects: []runtime.Object{
				&awsv1alpha1.Account{
					TypeMeta:   metav1.TypeMeta{Kind: "Account", APIVersion: "v1alpha1"},
					ObjectMeta: metav1.ObjectMeta{Name: "other-namespace", Namespace: "default"},
					Status: awsv1alpha1.AccountStatus{
						State: string(awsv1alpha1.AccountReady),
						OptInRegions: awsv1alpha1.OptInRegions{
							"af-south-1": &awsv1alpha1.OptInRegionStatus{RegionCode: "af-south-1", Status: awsv1alpha1.OptInRequestTodo},
						},
					},
				},
			},
			want: 0,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			fakeKubeClient := fake.NewClientBuilder().WithScheme(scheme.Scheme).WithRuntimeObjects(tt.objects...).Build()
			got, err := CalculateOptingInRegionAccounts(nullLogger, fakeKubeClient)
			if err != nil {
				t.Errorf("CalculateOptingInRegionAccounts() returned an error: %v", err)
			}
			if got != tt.want {
				t.Errorf("CalculateOptingInRegionAccounts() = %d, want %d", got, tt.want)
			}
		})
	}
}

func TestAccount_SetOptRegionStatus(t *testing.T) {
	err := apis.AddToScheme(scheme.Scheme)
	if err != nil {
		t.Fatalf("failed adding to scheme in region_enablement_test.go: %v", err)
	}

	nullLogger := testutils.NewTestLogger().Logger()

	tests := []struct {
		name       string
		optInRegions []string
		wantCount  int
		wantStatus awsv1alpha1.OptInRequestStatus
	}{
		{
			name:       "Sets all provided regions to todo",
			optInRegions: []string{"af-south-1", "ap-southeast-4"},
			wantCount:  2,
			wantStatus: awsv1alpha1.OptInRequestTodo,
		},
		{
			name:       "Empty region list results in empty status",
			optInRegions: []string{},
			wantCount:  0,
			wantStatus: awsv1alpha1.OptInRequestTodo,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			account := &awsv1alpha1.Account{}
			err := SetOptRegionStatus(nullLogger, tt.optInRegions, account)
			if err != nil {
				t.Errorf("SetOptRegionStatus() returned an error: %v", err)
			}
			if account.Status.OptInRegions == nil {
				t.Errorf("SetOptRegionStatus() did not set Status.OptInRegions")
			}
			if len(account.Status.OptInRegions) != tt.wantCount {
				t.Errorf("SetOptRegionStatus() set %d regions, want %d", len(account.Status.OptInRegions), tt.wantCount)
			}
			for _, region := range tt.optInRegions {
				if regionStatus, ok := account.Status.OptInRegions[region]; !ok {
					t.Errorf("SetOptRegionStatus() missing region %s in status", region)
				} else if regionStatus.Status != tt.wantStatus {
					t.Errorf("SetOptRegionStatus() region %s status = %v, want %v", region, regionStatus.Status, tt.wantStatus)
				}
			}
		})
	}
}

func TestAccount_ParseDisabledRegions(t *testing.T) {
	tests := []struct {
		name            string
		disabledRegions string
		want            map[string]bool
	}{
		{
			name:            "Empty string",
			disabledRegions: "",
			want:            map[string]bool{},
		},
		{
			name:            "Single region",
			disabledRegions: "ap-east-1",
			want:            map[string]bool{"ap-east-1": true},
		},
		{
			name:            "Multiple regions with whitespace",
			disabledRegions: "ap-east-1, af-south-1 ,ap-southeast-4",
			want:            map[string]bool{"ap-east-1": true, "af-south-1": true, "ap-southeast-4": true},
		},
		{
			name:            "Empty entries are skipped",
			disabledRegions: "ap-east-1,, af-south-1",
			want:            map[string]bool{"ap-east-1": true, "af-south-1": true},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := ParseDisabledRegions(tt.disabledRegions)
			if len(got) != len(tt.want) {
				t.Errorf("ParseDisabledRegions() = %v, want %v", got, tt.want)
				return
			}
			for region, wantVal := range tt.want {
				if got[region] != wantVal {
					t.Errorf("ParseDisabledRegions() = %v, want %v", got, tt.want)
				}
			}
		})
	}
}

func TestAccount_RegionNeedsOptIn(t *testing.T) {
	ctrl := gomock.NewController(t)
	defer ctrl.Finish()

	nullLogger := testutils.NewTestLogger().Logger()

	tests := []struct {
		name       string
