			}
			if got != tt.want {
				t.Errorf("RegionNeedsOptIn() = %v, want %v", got, tt.want)
			}
		})
	}
}

func TestAccount_checkOptInRegionStatus(t *testing.T) {
	ctrl := gomock.NewController(t)
