// ValidateOptInRegions enables supported opt-in regions for an existing ready non-CCS
// account when the feature flag is enabled. It records the pending enablement requests in the
// account status and initiates the enablement process, while respecting the concurrency limit
// on the number of accounts that may have region enablement in progress simultaneously.
func (r *AccountValidationReconciler) ValidateOptInRegions(reqLogger logr.Logger, currentAcctInstance *awsv1alpha1.Account, awsClientBuilder awsclient.IBuilder, optInRegions string, disabledRegions string) error {
	disabledSet := accountcontroller.ParseDisabledRegions(disabledRegions)
	var regionList []string
	regions := strings.Split(optInRegions, ",")
	for _, region := range regions {
		region = strings.TrimSpace(region)
		if region == "" {
			continue
		}
		if disabledSet[region] {
			reqLogger.Info("Skipping disabled region for opt-in validation", "region", region)
			continue
		}
		regionList = append(regionList, region)
	}

	if len(regionList) == 0 {
		reqLogger.Info("No opt-in regions to validate after filtering disabled regions")
		return nil
	}

	numberOfAccountsOptingIn, err := accountcontroller.CalculateOptingInRegionAccounts(reqLogger, r.Client)
	if err != nil {
		return &AccountValidationError{
			Type: NotAllOptInRegionsEnabled,
			Err:  err,
		}
	}

	if currentAcctInstance.Status.OptInRegions == nil || !currentAcctInstance.AllRegionsExistInOptInRegions(regionList) {
		if numberOfAccountsOptingIn >= accountcontroller.MaxAccountRegionEnablement {
			return &AccountValidationError{
				Type: TooManyActiveAccountRegionEnablements,
				Err:  errors.New("the request quota for the number of concurrent account region-OptIn requests has been reached"),
			}
		}
		// updates account status to indicate supported opt-in regions are pending enablement
		err = accountcontroller.SetOptRegionStatus(reqLogger, regionList, currentAcctInstance)
		if err != nil {
			return &AccountValidationError{
				Type: OptInRegionStatus,
				Err:  errors.New("failed to set account opt-in region status"),
			}
		}

		if currentAcctInstance.Spec.RegionalServiceQuotas != nil {
			currentAcctInstance.Status.RegionalServiceQuotas = make(awsv1alpha1.RegionalServiceQuotas)
		}
		err = r.statusUpdate(currentAcctInstance)
		if err != nil {
			return &AccountValidationError{
				Type: OptInRegionStatus,
				Err:  errors.New("failed to set account opt-in region status"),
			}
		}
	}
	awsRegion := config.GetDefaultRegion()
	awsSetupClient, err := awsClientBuilder.GetClient(controllerName, r.Client, awsclient.NewAwsClientInput{
		SecretName: utils.AwsSecretName,
		NameSpace:  awsv1alpha1.AccountCrNamespace,
		AwsRegion:  awsRegion,
	})
	if err != nil {
		connErr := fmt.Sprintf("unable to connect to default region %s", awsRegion)
		reqLogger.Error(err, connErr)
		return &AccountValidationError{
			Type: AWSErrorConnecting,
			Err:  errors.New("unexpected error attempting to connect to AWS in default region"),
		}
	}

	if currentAcctInstance.HasOpenOptInRegionRequests() && utils.DetectDevMode == utils.DevModeProduction {
		_, err := accountcontroller.GetOptInRegionStatus(reqLogger, r.awsClientBuilder, awsSetupClient, currentAcctInstance, r.Client)
		if err != nil {
			return &AccountValidationError{
				Type: NotAllOptInRegionsEnabled,
				Err:  err,
			}
		}
		return &AccountValidationError{
			Type: NotAllOptInRegionsEnabled,
			Err:  errors.New("not all Opt-In regions have been enabled yet"),
		}
	}
	return nil
}

func (r *AccountValidationReconciler) ValidateRegionalServiceQuotas(reqLogger logr.Logger, account *awsv1alpha1.Account, awsClientBuilder awsclient.IBuilder) error {
	awsRegion := config.GetDefaultRegion()
	awsSetupClient, err := awsClientBuilder.GetClient(controllerName, r.Client, awsclient.NewAwsClientInput{
		SecretName: utils.AwsSecretName,
		NameSpace:  awsv1alpha1.AccountCrNamespace,
		AwsRegion:  awsRegion,
	})
	if err != nil {
		connErr := fmt.Sprintf("unable to connect to default region %s", awsRegion)
		reqLogger.Error(err, connErr)
		return &AccountValidationError{
			Type: AWSErrorConnecting,
			Err:  errors.New("unexpected error attempting to connect to AWS in default region"),
		}
	}

	if account.Spec.RegionalServiceQuotas == nil {
		return nil
	}

	if account.Status.RegionalServiceQuotas == nil {
		err = accountcontroller.SetCurrentAccountServiceQuotas(reqLogger, awsClientBuilder, awsSetupClient, account, r.Client)
		if err != nil {
			reqLogger.Error(err, "failed to set account service quotas")
			return &AccountValidationError{
				Type: SettingServiceQuotasFailed,
				Err:  errors.New("failed to set account service quotas"),
			}
		}
		err = r.statusUpdate(account)
		if err != nil {
			return &AccountValidationError{
				Type: QuotaStatus,
				Err:  errors.New("failed to update account status"),
			}
		}

		return &AccountValidationError{
			Type: QuotaStatus,
			Err:  errors.New("service quota status updated, increase request needs to be sent to aws"),
		}
	} else {
		if account.HasOpenQuotaIncreaseRequests() && utils.DetectDevMode == utils.DevModeProduction {
			_, err = accountcontroller.GetServiceQuotaRequest(reqLogger, awsClientBuilder, awsSetupClient, account, r.Client)
			if err != nil {
				return &AccountValidationError{
					Type: NotAllServicequotasApplied,
					Err:  err,
				}
			}

			return &AccountValidationError{
				Type: NotAllServicequotasApplied,
				Err:  errors.New("Service Quotas not yet applied"),
			}
		}
	}

	return nil
}

